INSERT INTO public.articulos (id, ley_id, orden, identificador, contenido, tipo_articulo, titulo_nombre, capitulo_nombre) VALUES ('8239c84a-0002-59d1-9a7e-7783a0ad8755', '1ea09496-323b-5a12-b004-00977dd5eeb9', 1, 'Convocatoria · CFE-0400-CASAT-0003-2026', '<p>COMISION FEDERAL DE ELECTRICIDAD</p>
<p>Con fundamento en el Artículo 134 de la Constitución Política de los Estados Unidos Mexicanos, Artículos 80 y 82 de la Ley de la Empresa Pública del Estado, Comisión Federal de Electricidad (CFE), en las disposiciones 2 fracciones II, 30 fracción I, inciso b), 31, 33 fracciones IV, VII y VIII, 34, 37 y 56 fracciones III y IV de las Disposiciones Generales en Materia de adquisiciones, arrendamientos, contratación de servicios y ejecución de obras de la Comisión Federal de Electricidad (Disposiciones Generales):</p>
<table><tbody><tr><th scope="row">Número del Concurso:</th><td>CFE-0400-CASAT-0003-2026</td></tr><tr><th scope="row">Descripción del Concurso:</th><td>Actualización del sistema de control TOSMAP para la Central Ciclo Combinado Centro</td></tr><tr><th scope="row">Fecha de publicación en Micrositio:</th><td>11/11/2026</td></tr><tr><th scope="row">Aclaración a los documentos del Concurso:</th><td>18/11/2026, 10:00 hrs</td></tr><tr><th scope="row">Límite para presentación de ofertas:</th><td>26/11/2026,09:00 hrs</td></tr><tr><th scope="row">Apertura Técnica:</th><td>26/11/2026,10:00 hrs</td></tr><tr><th scope="row">Apertura Económica:</th><td>02/12/2026, 10:00 hrs</td></tr><tr><th scope="row">Fallo:</th><td>07/12/2026, 10:00 hrs</td></tr></tbody></table>
<p>El Area Contratante que publica la presente convocatoria es la Coordinación Regional de Producción Central de la CFE, con clave 0400, a través del Departamento Regional de Abastecimientos cuyo contacto es la Lic. Pamela Galván Carbajal, con domicilio en Av. Real de los Reyes No. 265, Col. Los Reyes, Alcaldía Coyoacán, C.P. 04330, Ciudad de México, teléfono (55) 52294400 ext. 40173, con el correo electrónico: pamela.galvanc@cfe.mx. Los interesados podrán obtener la Convocatoria y Pliego de Requisitos, a través del Micrositio de Concursos de CFE ubicado en el sitio https://msc.cfe.mx/Aplicaciones/NCFE/Concursos/, a partir de la fecha de publicación en el Micrositio.</p>
<p>CIUDAD DE MEXICO, A 11 DE NOVIEMBRE DE 2026.</p>
<p>ENCARGADO DEL DEPARTAMENTO REGIONAL DE ABASTECIMIENTOS</p>
<p>MTRO. ERIK MANUEL CETINA MAGAÑA</p>
<p>FIRMA ELECTRONICA.</p>
<p>(R.- 582383)</p>', 'convocatoria', 'CFE-0400-CASAT-0003-2026', 'Control TOSMAP de la Central Ciclo Combinado Centro');
